new='''def simple_paths(topo, rng, max_paths=4):
    """Valid routing plan: one bundle per ordered pair of distinct external nodes."""
    id_by_name = {n['name']: n['id'] for n in topo['nodes']}
    name_by_id = {n['id']: n['name'] for n in topo['nodes']}
    adj = {}
    for l in topo['links']:
        adj.setdefault(l['source'], set()).add(l['target'])
        adj.setdefault(l['target'], set()).add(l['source'])
    names = list(topo['external_nodes'])
    if len(names) < 2:
        return None if rng.random() < 0.5 else {}
    plan = {}
    for s in names:
        for d in names:
            if s == d:
                continue
            sid, did = id_by_name[s], id_by_name[d]
            found = []
            stack = [[sid]]
            while stack and len(found) < 40:
                path = stack.pop()
                if path[-1] == did:
                    found.append(path)
                    continue
                for nxt in sorted(adj.get(path[-1], ())):
                    if nxt not in path:
                        stack.append(path + [nxt])
            if not found:
                return None
            rng.shuffle(found)
            bundles = [p for p in found[:rng.randint(1, min(max_paths, len(found)))]
                       if 2 <= len(p) <= 33]
            if not bundles:
                bundles = [found[0]]
            weights = []
            total = 1000
            for i in range(len(bundles) - 1):
                w = rng.randint(1, max(1, total - (len(bundles) - 1 - i)))
                weights.append(w)
                total -= w
            weights.append(total)
            entries = [{'path': [name_by_id[p] for p in path], 'weight': w}
                       for path, w in zip(bundles, weights)]
            plan.setdefault(s, {})[d] = entries
    return plan


'''
